 S.apps.forEach(a=>{if(m(a.id+' '+nm(a.k)+' '+usr(a.k).sid))r.push({g:'Tutor Applications',t:a.id,s:`${nm(a.k)} · ${a.type} · ${a.st}`,a:'appOpen',v:a.id})});
