function bmList(){const f=S.bm,q=f.q.trim().toLowerCase();return S.bookings.filter(b=>(!q||(b.id+' '+nm(b.l)+' '+nm(b.t)+' '+srv(b.srv).title+' '+b.topic).toLowerCase().includes(q))&&(f.scope==='all'||(f.scope==='inc'?S.incidents.some(i=>i.bk===b.id):b.pay==='Refund Review'))&&(!f.quick||b.st===f.quick)&&(!f.qpay||b.pay===f.qpay)&&BDR[f.dr][1](b.d)&&(f.type==='Session Type'||b.type===f.type)&&(f.st==='Booking Status'||b.st===f.st)&&(f.pay==='Payment Status'||b.pay===f.pay)).sort((a,b)=>a.id<b.id?1:-1)}
const fTr=(a,b)=>{const x=fTs(a),y=fTs(b);return x.slice(-2)===y.slice(-2)?x.slice(0,-3)+' – '+y:x+' – '+y};
