const PDR={sep:['Sep 1, 2026 - Sep 30, 2026',d=>d.startsWith('2026-09')],aug:['Aug 1, 2026 - Aug 31, 2026',d=>d.startsWith('2026-08')],ytd:['Jan 1, 2026 - Sep 30, 2026',d=>d>='2026-01-01']};
